#include "core/abif_export.hpp"
#include "core/abif.hpp"
#include "core/session.hpp"
#include "abif_fixture.hpp"
#include <algorithm>
#include <functional>
#include <iostream>
#include <random>
#include <sstream>
#include <stdexcept>
using namespace kleiotide;
namespace {
void need(bool value,const char* message){if(!value)throw std::runtime_error(message);}
template<class F>void rejects(F f){bool threw=false;try{f();}catch(const std::exception&){threw=true;}need(threw,"Expected rejection");}
Document trace(std::string calls="aCgTRN",unsigned set=1){std::istringstream input(test::synthetic_abif(calls,set));Document d;d.load({read_abif(input,"sample Я","missing.ab1")});return d;}
std::string bytes(const AbifExport& p){std::ostringstream output(std::ios::binary);write_abif_export(output,p);return output.str();}
Record reread(const AbifExport& p){std::istringstream input(bytes(p),std::ios::binary);return read_abif(input,"exported","output.ab1");}
std::string ungap(const Sequence& row){std::string text;for(char c:row.symbols.text())if(!is_gap(c))text+=c;return text;}
std::string session(const Document& d){std::ostringstream output(std::ios::binary);write_session(output,d);return output.str();}
void check(const Document& d){const auto& row=d.sequence(1);auto p=prepare_abif_export(row);auto out=reread(p);need(out.symbols==ungap(row),"Every current residue survives exactly");need(out.trace->original->quality==p.quality&&out.trace->original->peaks==std::vector<std::uint32_t>(p.peaks.begin(),p.peaks.end()),"Call counts/peaks/quality match");const auto& original=*row.trace->original;for(std::size_t c=0;c<4;++c){const auto& expected=original.channels[row.trace->reversed?3-c:c];auto actual=out.trace->original->channels[c];if(row.trace->reversed)std::reverse(actual.begin(),actual.end());need(actual==expected,"Every signal sample retained in the proper orientation/channel");}}
}
int main(){int passed=0,failed=0;auto test=[&](const char* name,const std::function<void()>& f){try{f();++passed;std::cout<<"PASS "<<name<<'\n';}catch(const std::exception& e){++failed;std::cerr<<"FAIL "<<name<<": "<<e.what()<<'\n';}};
test("Unchanged calls preserve case, measured quality, positions, samples and both call-set imports",[]{for(unsigned set:{1U,2U}){auto d=trace("aCgTRN",set);const auto before=session(d);auto p=prepare_abif_export(d.sequence(1));need(!p.inserted&&!p.substituted&&p.measuredQuality==6&&p.sampleName=="sample Я","Quality and name summary");check(d);need(session(d)==before&&!d.can_undo(),"Export is read-only");}});
test("Substitutions, insertion, deletion and both gap states export current ungapped sequence",[]{auto d=trace("ACGTRN");d.replace(1,2,1,"n");d.replace(1,4,0,"aR");d.replace(1,0,1,"");d.replace(1,2,0,"-~~");const auto before=session(d);const auto state=d.state_id();auto p=prepare_abif_export(d.sequence(1));need(p.inserted==2&&p.substituted==1&&p.omittedGaps==3,"Edit categories");std::size_t i=0;for(auto anchor:d.sequence(1).trace->originalCalls){if(anchor<0||i==1)need(p.quality[i]==0,"New/changed calls have zero Q");++i;}check(d);need(session(d)==before&&d.state_id()==state,"Source unchanged");});
test("Inserted runs at both ends, crowded samples and entirely unanchored sequence survive",[]{auto d=trace("ACGTAC");d.replace(1,0,0,std::string(60,'N'));d.replace(1,d.sequence(1).symbols.size(),0,std::string(80,'n'));d.replace(1,63,0,std::string(80,'A'));auto p=prepare_abif_export(d.sequence(1));need(p.inserted==220&&p.coincident>0,"Crowded inserted calls retained rather than dropped");check(d);auto empty=trace();empty.replace(1,0,empty.sequence(1).symbols.size(),"");empty.replace(1,0,0,"tRaCGN");p=prepare_abif_export(empty.sequence(1));need(p.inserted==6&&p.measuredQuality==0&&std::all_of(p.quality.begin(),p.quality.end(),[](auto q){return q==0;}),"Unanchored calls get interpolated positions and no invented Q");check(empty);});
test("Reverse complement changes all signal axes/channels, positions and qualities consistently",[]{auto d=trace("aCgTRN");d.replace(1,2,0,"N");d.transform({1},Document::Transform::ReverseComplement);auto p=prepare_abif_export(d.sequence(1));need(p.reversed&&p.inserted==1&&!p.substituted,"RC preserves original-call identity");check(d);d.transform({1},Document::Transform::ReverseComplement);check(d);});
test("Inline tags with 1-4 calls and coincident original peak positions are valid",[]{for(const auto& calls:{"A","AC","ACG","ACGT"}){auto d=trace(calls);check(d);}auto d=trace();auto data=std::make_shared<Chromatogram>(*d.sequence(1).trace->original);data->peaks[1]=data->peaks[0];auto link=std::make_shared<TraceLink>(*d.sequence(1).trace);link->original=data;Document same;same.load({{"same",data->calls,RowKind::Nucleotide,link}});need(prepare_abif_export(same.sequence(1)).coincident==1,"Original coincident peaks retained");check(same);});
test("Missing quality becomes zero and full byte-quality range is retained",[]{for(bool absent:{false,true}){auto d=trace();auto data=std::make_shared<Chromatogram>(*d.sequence(1).trace->original);if(absent)data->quality.clear();else data->quality={0,127,128,200,254,255};auto link=std::make_shared<TraceLink>(*d.sequence(1).trace);link->original=data;Document edited;edited.load({{"sample",data->calls,RowKind::Nucleotide,link}});auto p=prepare_abif_export(edited.sequence(1));need(absent?p.missingQuality==6:p.measuredQuality==6,"Missing/measured Q counts");check(edited);}});
test("Unsigned 16-bit signal and peak ranges are encoded without wrap or truncation",[]{auto d=trace();auto data=std::make_shared<Chromatogram>(*d.sequence(1).trace->original);for(auto& channel:data->channels){channel.resize(70000,0);for(auto& v:channel)v=std::max(0,v);channel[40]=65000;}for(std::size_t i=0;i<data->peaks.size();++i)data->peaks[i]=40000+static_cast<std::uint32_t>(i)*20;auto link=std::make_shared<TraceLink>(*d.sequence(1).trace);link->original=data;Document wide;wide.load({{"wide",data->calls,RowKind::Nucleotide,link}});need(prepare_abif_export(wide.sequence(1)).channelTypes[0]==3,"Unsigned amplitudes use word type");check(wide);});
test("Unsupported traces, empty calls, incompatible amplitudes and corrupt plans reject",[]{Document no;no.load({{"plain","ACGT"},{"protein","MEF",RowKind::Protein}});rejects([&]{prepare_abif_export(no.sequence(1));});rejects([&]{prepare_abif_export(no.sequence(2));});auto d=trace();d.replace(1,0,d.sequence(1).symbols.size(),"~~-");rejects([&]{prepare_abif_export(d.sequence(1));});
    for(int amplitude:{-32769,65536}){auto original=trace();auto data=std::make_shared<Chromatogram>(*original.sequence(1).trace->original);data->channels[0][0]=amplitude;auto link=std::make_shared<TraceLink>(*original.sequence(1).trace);link->original=data;Document wide;wide.load({{"wide",data->calls,RowKind::Nucleotide,link}});rejects([&]{prepare_abif_export(wide.sequence(1));});}
    auto original=trace();auto p=prepare_abif_export(original.sequence(1));auto bad=p;bad.calls="!";rejects([&]{bytes(bad);});bad=p;bad.peaks.pop_back();rejects([&]{bytes(bad);});bad=p;std::swap(bad.peaks[0],bad.peaks[1]);rejects([&]{bytes(bad);});bad=p;bad.channelTypes[0]=5;rejects([&]{bytes(bad);});
});
test("UTF-8 sample names are bounded at complete characters and portable sessions need no original AB1",[]{auto d=trace();std::string name;for(int i=0;i<200;++i)name+="Я";d.rename({{1,name}});const auto saved=session(d);std::istringstream input(saved,std::ios::binary);auto portable=read_session(input);auto p=prepare_abif_export(portable.document.sequence(1));auto out=reread(p);need(out.trace->original->sampleName.size()==126&&out.trace->original->sampleName==name.substr(0,126),"pString truncates UTF-8 at a codepoint boundary");check(portable.document);});
test("Legacy-reader layout keeps payloads before the directory and supplies honest unknown fields",[]{
    auto d=trace("ACGTACGTACGT");d.rename({{1,"PBAS PLOC DATA SMPL SVER"}});const auto file=bytes(prepare_abif_export(d.sequence(1)));
    auto number=[&](std::size_t at,unsigned width){std::uint32_t v=0;for(unsigned i=0;i<width;++i)v=(v<<8)|static_cast<unsigned char>(file.at(at+i));return v;};
    const auto directory=number(26,4),count=number(18,4);need(directory+count*28==file.size(),"Directory ends at EOF, beyond every external payload");unsigned dataCount=0;
    for(std::size_t i=0;i<count;++i){const auto at=directory+i*28;const auto tag=file.substr(at,4);const auto n=number(at+4,4),length=number(at+16,4);if(length>4)need(number(at+20,4)+length<=directory,"No tag data after directory");if(tag=="DATA"){need(n==++dataCount,"DATA entries consecutive 1-12 for ordinal readers");if(n<9)need(length==0,"No fabricated acquisition/auxiliary samples");}if(number(at+8,2)==18){const auto start=length<=4?at+20:number(at+20,4);need(static_cast<unsigned char>(file.at(start))<=127,"Pascal metadata lengths safe for signed-byte readers");}}
    need(dataCount==12,"All legacy DATA entries present");check(d);
});
test("Cancellation and failed output do not mutate source evidence or history",[]{auto d=trace();const auto before=session(d);rejects([&]{prepare_abif_export(d.sequence(1),[]{return true;});});auto p=prepare_abif_export(d.sequence(1));std::ostringstream out;rejects([&]{write_abif_export(out,p,[]{return true;});});need(out.str().empty(),"Cancelled before writing");out.setstate(std::ios::badbit);rejects([&]{write_abif_export(out,p);});need(session(d)==before&&!d.can_undo(),"Failures are read-only");});
test("Randomized edits, slides and reversal retain every current call and signal sample",[]{std::mt19937 rng(314159);for(int trial=0;trial<75;++trial){auto d=trace("ACGTACGTACGTACGT");for(int step=0;step<20;++step){const auto n=d.sequence(1).symbols.size();const auto at=n?rng()%(n+1):0;const auto op=rng()%4;if(op==0)d.replace(1,at,0,std::string(1,"ACGTNR?~"[rng()%8]));else if(op==1&&at<n)d.replace(1,at,1,std::string(1,"acgtNR?-"[rng()%8]));else if(op==2&&at<n)d.replace(1,at,1,"");else if(op==3)d.transform({1},Document::Transform::ReverseComplement);}if(d.sequence(1).symbols.residue_count()){const auto before=session(d);check(d);need(session(d)==before,"Random export does not change history data");}}});
std::cout<<passed<<" passed, "<<failed<<" failed\n";return failed?1:0;}
